import inquirer from "inquirer";
import { errAsync, okAsync, ResultAsync } from "neverthrow";
import { extract } from "tar-stream";

import { toErrorWithMessage } from "@/utils/error";

export class FilesystemService {
  constructor(
    private spinner: Ora,
    private yesToAll?: boolean,
  ) {}

  exists(directory: string, mode?: number): ResultAsync<boolean, ErrorWithMessage> {
    this.spinner.start("Checking directory existence");

    return ResultAsync.fromPromise(
      access(directory, mode)
        .then(() => true)
        .catch(() => false),
      toErrorWithMessage,
    ).map((exists) => {
      return exists;
    });
  }

  removeDirectory(directory: string): ResultAsync<void, ErrorWithMessage> {
    this.spinner.start(`Removing directory ${directory}`);
    return ResultAsync.fromPromise(rm(directory, { recursive: true }), toErrorWithMessage).map(() => {
      this.spinner.succeed(`Removed directory ${directory}`);
    });
  }

  createDirectory(directory: string): ResultAsync<string, ErrorWithMessage> {
    this.spinner.start(`Creating directory ${directory}`);

    const resolved = path.resolve(directory);

    return this.exists(resolved).andThen((exists) => {
      if (exists) {
        if (this.yesToAll) {
          this.spinner.text = `Emptying directory ${resolved}`;
          return ResultAsync.fromPromise(emptyDir(directory), toErrorWithMessage).map(() => {
            this.spinner.succeed(`Directory ${directory} emptied`);

            return resolved;
          });
        }

        this.spinner.stop();
        return ResultAsync.fromPromise(
          inquirer.prompt([
            {
              type: "confirm",
              name: "overwrite",
              message: `Directory ${resolved} already exists. Overwrite?`,
            },
          ]),
          toErrorWithMessage,
        ).andThen((answer) => {
          if (!answer.overwrite) {
            this.spinner.succeed(`Using existing directory ${resolved}`);
            return okAsync(resolved);
          }

          this.spinner.text = `Emptying directory ${resolved}`;
          return ResultAsync.fromPromise(emptyDir(directory), toErrorWithMessage).map(() => {
            this.spinner.succeed(`Directory ${directory} emptied`);

            return resolved;
          });
        });
      }

      return ResultAsync.fromPromise(mkdir(resolved, { recursive: true }), toErrorWithMessage).andThen((res) => {
        if (res === undefined) {
          this.spinner.fail(`Failed to create directory ${directory}`);
          return errAsync({
            message: `Failed to create directory ${directory}`,
          });
        }
        this.spinner.succeed(`Created directory ${directory}`);
        return okAsync(resolved);
      });
    });
  }

  getAbsolutePath(directory: string): string {
    return path.resolve(directory);
  }

  private handleNonEmptyDirectory(directory: string): ResultAsync<string, ErrorWithMessage> {
    if (this.yesToAll) {
      return this.emptyDirectory(directory);
    }

    return ResultAsync.fromPromise(
      inquirer.prompt([
        {
          type: "confirm",
          name: "emptyDir",
          message: `Directory ${directory} is not empty. Empty it?`,
          default: true,
        },
      ]),
      toErrorWithMessage,
    ).andThen((answer) => {
      if (!answer.emptyDir) {
        this.spinner.warn(`Directory ${directory} is not empty. Continuing may overwrite existing files.`);
        return okAsync(directory);
      }

      return this.emptyDirectory(directory);
    });
  }

  emptyDirectory(directory: string): ResultAsync<string, ErrorWithMessage> {
    this.spinner.text = `Emptying directory ${directory}`;
    return ResultAsync.fromPromise(emptyDir(directory), toErrorWithMessage).map(() => {
      this.spinner.succeed(`Directory ${directory} emptied`);
      return directory;
    });
  }

  private decompressStream(buffer: ArrayBuffer): ResultAsync<void, ErrorWithMessage> {
    this.spinner.start("Decompressing dataset");

    return ResultAsync.fromPromise(
      new Promise<string>((resolve, reject) => {
        const extraction = extract();
        let jsonContent = "";

        extraction.on("entry", (header, stream, next) => {
          if (header.name.endsWith(".jsonl")) {
            stream.on("data", (chunk) => {
              jsonContent += chunk;
            });
          }
          stream.on("end", () => next());
          stream.resume();
        });

        extraction.on("finish", () => {
          resolve(jsonContent);
        });

        extraction.on("error", (err) => {
          // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors
          reject(toErrorWithMessage(err));
        });

        const readable = Readable.from(Buffer.from(buffer));
        readable.pipe(gunzip()).pipe(extraction);
      }),
      toErrorWithMessage,
    )
      .andThen((jsonContent) => {
        return ResultAsync.fromPromise(
          mkdir("data", { recursive: true }).then(() => writeFile("data/data.json", jsonContent)),
          toErrorWithMessage,
        );
      })
      .map(() => {
        this.spinner.succeed("Dataset decompressed and saved successfully");
      });
  }

  downloadTypesenseDataset(url: string): ResultAsync<void, ErrorWithMessage> {
    this.spinner.start(`Downloading dataset from ${url}`);

    return ResultAsync.fromPromise(fetch(url), toErrorWithMessage)
      .andThen((response) => {
        if (!response.ok) {
          return errAsync({
            message: `Failed to download dataset: ${response.statusText}`,
          });
        }

        return ResultAsync.fromPromise(response.arrayBuffer(), toErrorWithMessage);
      })
      .andThen((buffer) => this.decompressStream(buffer))
      .map(() => {
        this.spinner.succeed(`Dataset downloaded successfully`);
      });
  }

  private handleNonExistingDirectory(directory: string): ResultAsync<string, ErrorWithMessage> {
    if (this.yesToAll) {
      return ResultAsync.fromPromise(mkdir(directory, { recursive: true }), toErrorWithMessage).map(() => directory);
    }

    return ResultAsync.fromPromise(
      inquirer.prompt([
        {
          type: "confirm",
          name: "createDir",
          message: `Directory ${directory} does not exist. Create directory?`,
          default: true,
        },
      ]),
      toErrorWithMessage,
    ).andThen((answer) => {
      if (!answer.createDir) {
        return errAsync({
          message: `Directory ${directory} does not exist.`,
        });
      }

      this.spinner.text = `Save directory ${directory} does not exist. Creating directory`;
      return ResultAsync.fromPromise(mkdir(directory, { recursive: true }), toErrorWithMessage).map(() => directory);
    });
  }

  validateWorkingDirectory(directory: string): ResultAsync<string, ErrorWithMessage> {
    const resolved = path.resolve(directory);

    return this.exists(resolved).andThen((exists) => {
      if (exists) {
        this.spinner.succeed(`Working directory verified: ${resolved}`);
        return ResultAsync.fromPromise(readdir(resolved), toErrorWithMessage).andThen((files) => {
          if (files.length > 0) {
            return this.handleNonEmptyDirectory(resolved);
          }
          return okAsync(resolved);
        });
      }

      this.spinner.stop();
      return this.handleNonExistingDirectory(resolved);
    });
  }
}

import path from "path";
import type { DockerService } from "@/services/docker";
import type { ErrorWithMessage } from "@/utils/error";
import type { StdOut } from "@/utils/execa";
import type { ResultAsync } from "neverthrow";
import type { Ora } from "ora";

import { errAsync, okAsync } from "neverthrow";

import { DEFAULT_TYPESENSE_DIRECTORY } from "@/services/typesense-dir";
import { safeExeca } from "@/utils/execa";
import { logger } from "@/utils/logger";

export const DEFAULT_TYPESENSE_GIT_URL = "https://github.com/typesense/typesense.git";

export class GitService {
  private readonly url: string;
  private readonly directory: string;

  constructor(
    private spinner: Ora,
    url?: string,
    directory?: string,
    private execContext?: {
      containerName: string;
      dockerService: DockerService;
    },
  ) {
    this.url = url ?? DEFAULT_TYPESENSE_GIT_URL;
    this.directory = directory ?? DEFAULT_TYPESENSE_DIRECTORY;
  }

  private execCommand(args: string[], isClone?: true): ResultAsync<StdOut, ErrorWithMessage> {
    if (this.execContext) {
      return this.execContext.dockerService.execInContainer(this.execContext.containerName, `git ${args.join(" ")}`);
    }

    // Use process.cwd() only for clone operations, this.directory for everything else
    const cwd = isClone ? process.cwd() : this.directory;

    logger.debug(`Executing locally: git ${args.join(" ")}`);
    return safeExeca("git", args, { cwd }).map(({ stdout }) => stdout);
  }

  checkoutToCommit(commitHash?: string): ResultAsync<string, ErrorWithMessage> {
    this.spinner.color = "cyan";

    return this.execCommand(["fetch", "origin"])
      .andThen(() =>
        this.execCommand(["pull", "origin"]).orElse((err) => {
          if (err.message.includes("You are not currently on a branch")) {
            return this.switchBack().andThen(() => this.execCommand(["pull", "origin"]));
          }
          return errAsync(err);
        }),
      )
      .andThen(() => {
        return commitHash ? okAsync(commitHash) : this.revParseHead().map((head) => head);
      })
      .andThen((targetCommit) => {
        this.spinner.start(`Switching to commit ${targetCommit}`);
        return this.execCommand(["checkout", targetCommit]).andThen(() =>
          this.revParseHead().andThen((currentCommit) => {
            if (commitHash) {
              const minLen = Math.min(commitHash.length, currentCommit.length);

              const trimmedCurrentCommit = currentCommit.slice(0, minLen);
              const trimmedCommitHash = commitHash.slice(0, minLen);

              if (trimmedCurrentCommit !== trimmedCommitHash) {
                return this.switchBack().andThen(() => errAsync({ message: "Failed to checkout to commit" }));
              }
            }

            this.spinner.succeed(`Checked out to ${commitHash ? "commit" : "HEAD"} ${targetCommit}`);
            return okAsync(targetCommit);
          }),
        );
      });
  }

  switchBack(): ResultAsync<void, ErrorWithMessage> {
    this.spinner.start("Switching back to the original commit");

    return this.execCommand(["switch", "-"]).map(() => {
      this.spinner.succeed("Switched back to the original commit");
    });
  }

  revParseHead(): ResultAsync<string, ErrorWithMessage> {
    const args = ["rev-parse", "HEAD"];
    logger.debug(`Getting HEAD commit with command: git ${args.join(" ")}`);
    this.spinner.start("Getting HEAD commit");

    return this.execCommand(args).andThen((stdout) => {
      if (typeof stdout === "string") {
        logger.debug(`HEAD commit is: ${stdout}`);
        return okAsync(stdout);
      }

      return errAsync({ message: "Failed to get HEAD commit" });
    });
  }

  markDirectoryAsSafe(directory: string): ResultAsync<string, ErrorWithMessage> {
    const args = ["config", "--global", "--add", "safe.directory", directory];
    logger.debug(`Marking directory as safe with command: git ${args.join(" ")}`);

    this.spinner.start("Marking directory as safe");

    return this.execCommand(args).map(() => {
      this.spinner.succeed("Directory marked as safe");
      return directory;
    });
  }

  cloneRepository(): ResultAsync<string, ErrorWithMessage> {
    const args = ["clone", this.url, this.directory];
    logger.debug(`Cloning into repository with command: git ${args.join(" ")}`);

    this.spinner.start("Cloning git repository");
    return this.execCommand(args, true).map(() => {
      this.spinner.succeed("Repository cloned successfully");
      return path.resolve(this.directory);
    });
  }
}

import path from "path";
import type { TypesenseProcessManager } from "@/services/typesense-process";
import type { ErrorWithMessage } from "@/utils/error";
